SourceCode.Declaration:
/// <summary>
/// DebuC 05.10.23
/// </summary>
public class NDXTmpKumUmsCustArtGrp extends common
{
}

Method.Source:
/// <summary>
/// DebuC 05.10.23
/// last modified PaffH 05.05.25
/// </summary>
/// <param name = "umsSignature">NDXUmsSignature</param>
/// <param name = "monthYearSignature">NDXMonthYearSignature</param>
/// <param name = "alliance">CustAccount</param>
/// <param name = "lWithProt">boolean</param>
/// <param name = "nDXUmsatzClass">nDXUmsatzClass</param>
static server void setUmsatzCS( NDXUmsSignature            umsSignature,
                            NDXMonthYearSignature       monthYearSignature,
                            CustAccount                 alliance,
                            boolean                     lWithProt,
                            nDXUmsatzClass              nDXUmsatzClass)
{
    NDXTmpKumUmsCustArtGrp          nDXTmpKumUmsCustArtGrp;
    NDXTmpKumUmsCustArtGrp          nDXTmpKumUmsCustArtGrpAll;
    NDXTmpCSAllianceArtGrp          nDXTmpCSAllianceArtGrp;
    NDXTmpCSAllianceArtGrp          nDXTmpCSAllianceArtGrpGrp;
    NDXArtGrp                       nDX_ArtGrp;
    NDXTmpCustomerAlliance          nDXTmpCustomerAlliance;
    NDXCompanyBE                    firma, lfirma;
    boolean                         lTestImport = false;        
    CustAccount                     child;
    CustTable                       custTablePartyId;
    str infoAddition;
    System.Exception ex;

    //Gruppierung: Artikelgruppe des Zentrallagerumsatzes
    try
    {
        firma = NDXCompanyBE::WithoutAssignment;
        ttsbegin;
        while select    nDXTmpCSAllianceArtGrpGrp
        group by    Alliance, CustAccount, Company, ArtGrp
        where       nDXTmpCSAllianceArtGrpGrp.UmsSignature         == umsSignature         &&
                    nDXTmpCSAllianceArtGrpGrp.MonthYearSignature   == monthYearSignature   &&
                    nDXTmpCSAllianceArtGrpGrp.Alliance             == alliance
        {
            if (lWithProt)
            {
                NDXUmsatzProt::add(umsSignature, "@NDX:NDXAddSalesVoumeShares2", NDXProtStart::Start, 2);             // Artikelgruppenumsatz-ZL-Anteile den Artikelgruppenumsätzen zufügen 2
            }

            lfirma = NDXHelperCommon::CompanyId2NDXCompany(nDXTmpCSAllianceArtGrpGrp.Company, lTestImport);
            if (firma != lfirma)
            {
                firma = lfirma;
                custTablePartyId = NDXUmsatzClass::getCustTableFromAccount(alliance, firma);
            }
            if (nDXUmsatzClass.parmPartyIdCalculated())
            {
                custTablePartyId = CustTable::findByPartyRecId(nDXUmsatzClass.parmPartyIdCalculated());
            }
            child = NDXTmpCSAllianceArtGrpGrp.CustAccount;
            //Artikelgruppe des Debitoren
            if (nDXUmsatzClass.parmPartyIdCalculated())
            {
                nDXTmpKumUmsCustArtGrp = NDXTmpKumUmsCustArtGrp::findPartyId(umsSignature,
                                                                    monthYearSignature,
                                                                    nDXUmsatzClass.parmPartyIdCalculated(),
                                                                    firma,
                                                                    NDXTmpCSAllianceArtGrpGrp.ArtGrp,
                                                                    true);
                nDXTmpKumUmsCustArtGrpAll = NDXTmpKumUmsCustArtGrp::findPartyId(umsSignature,
                                                                    monthYearSignature,
                                                                    nDXUmsatzClass.parmPartyIdCalculated(),
                                                                    NDXCompanyBE::AllCompanies,
                                                                    NDXTmpCSAllianceArtGrpGrp.ArtGrp,
                                                                    true);
            }
            else
            {
                nDXTmpKumUmsCustArtGrp = NDXTmpKumUmsCustArtGrp::find(umsSignature,
                                                                    monthYearSignature,
                                                                    nDXTmpCSAllianceArtGrpGrp.Alliance,
                                                                    child,
                                                                    firma,
                                                                    NDXTmpCSAllianceArtGrpGrp.ArtGrp,
                                                                    true);
                nDXTmpKumUmsCustArtGrpAll = NDXTmpKumUmsCustArtGrp::find(umsSignature,
                                                                    monthYearSignature,
                                                                    nDXTmpCSAllianceArtGrpGrp.Alliance,
                                                                    child,
                                                                    NDXCompanyBE::AllCompanies,
                                                                    NDXTmpCSAllianceArtGrpGrp.ArtGrp,
                                                                    true);
            }

            // Falls Debitor für diese Gruppe keinen Umsatz gemacht hat, diesen anlegen
            if (!nDXTmpKumUmsCustArtGrp)
            {

                nDX_ArtGrp = NDXArtGrp::find(nDXTmpCSAllianceArtGrpGrp.ArtGrp, '', '');
                nDXTmpKumUmsCustArtGrp.UmsSignature        = umsSignature;
                nDXTmpKumUmsCustArtGrp.MonthYearSignature  = monthYearSignature;
                nDXTmpKumUmsCustArtGrp.Alliance            = nDXTmpCSAllianceArtGrpGrp.Alliance;
                nDXTmpKumUmsCustArtGrp.Child               = child;
                nDXTmpKumUmsCustArtGrp.ItemGroup           = nDXTmpCSAllianceArtGrpGrp.ArtGrp;
                nDXTmpKumUmsCustArtGrp.Name                = nDX_ArtGrp.BEZ;
                nDXTmpKumUmsCustArtGrp.Company             = firma;
                nDXTmpKumUmsCustArtGrp.Party             = custTablePartyId.Party;                 // 1.3: NDX/PAFFH/NDX_TASK1235003633/10.12.2014
                nDXTmpKumUmsCustArtGrp.PartyChild        = CustTable::find(nDXTmpKumUmsCustArtGrp.Child).Party;           // 1.4: NDX/PAFFH/NDX_TASK1235004221/03.02.2018
            }
            if (!nDXTmpKumUmsCustArtGrpAll)
            {
                nDX_ArtGrp = NDXArtGrp::find(nDXTmpCSAllianceArtGrpGrp.ArtGrp, '', '');
                nDXTmpKumUmsCustArtGrpAll.UmsSignature         = umsSignature;
                nDXTmpKumUmsCustArtGrpAll.MonthYearSignature   = monthYearSignature;
                nDXTmpKumUmsCustArtGrpAll.Alliance             = nDXTmpCSAllianceArtGrpGrp.Alliance;
                nDXTmpKumUmsCustArtGrpAll.Child                = child;
                nDXTmpKumUmsCustArtGrpAll.ItemGroup            = nDXTmpCSAllianceArtGrpGrp.ArtGrp;
                nDXTmpKumUmsCustArtGrpAll.Name                 = nDX_ArtGrp.BEZ;
                nDXTmpKumUmsCustArtGrpAll.Company                = NDXCompanyBE::AllCompanies;
                nDXTmpKumUmsCustArtGrpAll.Party                = custTablePartyId.Party;                 // 1.3: NDX/PAFFH/NDX_TASK1235003633/10.12.2014
                nDXTmpKumUmsCustArtGrpAll.PartyChild           = CustTable::find(nDXTmpKumUmsCustArtGrp.Child).Party;           // 1.4: NDX/PAFFH/NDX_TASK1235004221/03.02.2018
                nDXTmpKumUmsCustArtGrpAll.setUmsLfdJTmpKumUmsCustArtGrp(nDXTmpKumUmsCustArtGrp);
                nDXTmpKumUmsCustArtGrpAll.setUmsVJTmpKumUmsCustArtGrp(nDXTmpKumUmsCustArtGrp);
            }

            // Umsatzwerte der Artikelgruppe der Zentrallager ermitteln
            select      sum(U01) , sum(U02) , sum(U03) , sum(U04) , sum(U05) , sum(U06) , sum(U07) , sum(U08) , sum(U09) , sum(U10) , sum(U11) , sum(U12) ,
                        sum(VU01), sum(VU02), sum(VU03), sum(VU04), sum(VU05), sum(VU06), sum(VU07), sum(VU08), sum(VU09), sum(VU10), sum(VU11), sum(VU12),
                        sum(C01) , sum(C02) , sum(C03) , sum(C04) , sum(C05) , sum(C06) , sum(C07) , sum(C08) , sum(C09) , sum(C10) , sum(C11) , sum(C12) ,
                        sum(VC01), sum(VC02), sum(VC03), sum(VC04), sum(VC05), sum(VC06), sum(VC07), sum(VC08), sum(VC09), sum(VC10), sum(VC11), sum(VC12)
            from        nDXTmpCSAllianceArtGrp
            where       nDXTmpCSAllianceArtGrp.UmsSignature        == umsSignature                             &&
                        nDXTmpCSAllianceArtGrp.MonthYearSignature  == monthYearSignature                       &&
                        nDXTmpCSAllianceArtGrp.Exclude             == NoYes::No                                &&
                        nDXTmpCSAllianceArtGrp.Company             == nDXTmpCSAllianceArtGrpGrp.Company       &&
                        nDXTmpCSAllianceArtGrp.Alliance            == nDXTmpCSAllianceArtGrpGrp.Alliance      &&
                        nDXTmpCSAllianceArtGrp.CustAccount         == nDXTmpCSAllianceArtGrpGrp.CustAccount   &&
                        nDXTmpCSAllianceArtGrp.ArtGrp              == nDXTmpCSAllianceArtGrpGrp.ArtGrp;

            nDXTmpKumUmsCustArtGrp.UCSShare                = nDXTmpCSAllianceArtGrp.UJahr();
            nDXTmpKumUmsCustArtGrp.VUCSShare               = nDXTmpCSAllianceArtGrp.VUJahr();
            nDXTmpKumUmsCustArtGrp.CCSShare                = nDXTmpCSAllianceArtGrp.CJahr();
            nDXTmpKumUmsCustArtGrp.VCCSShare               = nDXTmpCSAllianceArtGrp.VCJahr();
            nDXTmpKumUmsCustArtGrp.UCSShareExcl            = nDXTmpKumUmsCustArtGrp.getUmsLfdJahr();
            nDXTmpKumUmsCustArtGrp.VUCSShareExcl           = nDXTmpKumUmsCustArtGrp.getUmsVJahr();
            nDXTmpKumUmsCustArtGrp.UACSShare               = nDXUmsatzClass.UAJahrNDXTmpCSAllianceArtGrp(nDXTmpCSAllianceArtGrp);
            nDXTmpKumUmsCustArtGrp.VUACSShare              = nDXUmsatzClass.VUAJahrNDXTmpCSAllianceArtGrp(nDXTmpCSAllianceArtGrp);
            nDXTmpKumUmsCustArtGrp.UACSShareExcl           = nDXUmsatzClass.UAJahrNDXTmpKumUmsCustArtGrp(nDXTmpKumUmsCustArtGrp);
            nDXTmpKumUmsCustArtGrp.VUACSShareExcl          = nDXUmsatzClass.VUAJahrNDXTmpKumUmsCustArtGrp(nDXTmpKumUmsCustArtGrp);
            nDXTmpKumUmsCustArtGrp.U                       = nDXTmpKumUmsCustArtGrp.UCSShareExcl + nDXTmpKumUmsCustArtGrp.UCSShare;
            nDXTmpKumUmsCustArtGrp.UCSSharePercent         = nDXTmpKumUmsCustArtGrp.U ? (nDXTmpKumUmsCustArtGrp.UCSShare * 100)  / nDXTmpKumUmsCustArtGrp.U   : 0;
            nDXTmpKumUmsCustArtGrp.VU                      = nDXTmpKumUmsCustArtGrp.VUCSShareExcl + nDXTmpKumUmsCustArtGrp.VUCSShare;
            nDXTmpKumUmsCustArtGrp.VUCSSharePercent        = nDXTmpKumUmsCustArtGrp.VU ? (nDXTmpKumUmsCustArtGrp.VUCSShare * 100) / nDXTmpKumUmsCustArtGrp.VU : 0;
            nDXTmpKumUmsCustArtGrp.setDiffValuesPercent(nDXUmsatzClass, true);
            if (nDXTmpKumUmsCustArtGrp.validateWrite())
            {
                nDXTmpKumUmsCustArtGrp.write();
            }

            nDXTmpKumUmsCustArtGrpAll.UCSShare             = nDXTmpCSAllianceArtGrp.UJahr();
            nDXTmpKumUmsCustArtGrpAll.VUCSShare            = nDXTmpCSAllianceArtGrp.VUJahr();
            nDXTmpKumUmsCustArtGrpAll.CCSShare             = nDXTmpCSAllianceArtGrp.CJahr();
            nDXTmpKumUmsCustArtGrpAll.VCCSShare            = nDXTmpCSAllianceArtGrp.VCJahr();
            nDXTmpKumUmsCustArtGrpAll.UCSShareExcl         =  nDXTmpKumUmsCustArtGrp.getUmsLfdJahr();
            nDXTmpKumUmsCustArtGrpAll.VUCSShareExcl        =  nDXTmpKumUmsCustArtGrp.getUmsVJahr();
            nDXTmpKumUmsCustArtGrpAll.UACSShare            = nDXUmsatzClass.UAJahrNDXTmpCSAllianceArtGrp(nDXTmpCSAllianceArtGrp);
            nDXTmpKumUmsCustArtGrpAll.VUACSShare           = nDXUmsatzClass.VUAJahrNDXTmpCSAllianceArtGrp(nDXTmpCSAllianceArtGrp);
            nDXTmpKumUmsCustArtGrpAll.UACSShareExcl        = nDXUmsatzClass.UAJahrNDXTmpKumUmsCustArtGrp(nDXTmpKumUmsCustArtGrp);
            nDXTmpKumUmsCustArtGrpAll.VUACSShareExcl       = nDXUmsatzClass.VUAJahrNDXTmpKumUmsCustArtGrp(nDXTmpKumUmsCustArtGrp);
            nDXTmpKumUmsCustArtGrpAll.U                    = nDXTmpKumUmsCustArtGrpAll.UCSShareExcl + nDXTmpKumUmsCustArtGrpAll.UCSShare;
            nDXTmpKumUmsCustArtGrpAll.UCSSharePercent      = nDXTmpKumUmsCustArtGrpAll.U ? (nDXTmpKumUmsCustArtGrpAll.UCSShare * 100)  / nDXTmpKumUmsCustArtGrpAll.U   : 0;
            nDXTmpKumUmsCustArtGrpAll.VU                   = nDXTmpKumUmsCustArtGrpAll.VUCSShareExcl + nDXTmpKumUmsCustArtGrpAll.VUCSShare;
            nDXTmpKumUmsCustArtGrpAll.VUCSSharePercent     = nDXTmpKumUmsCustArtGrpAll.VU ? (nDXTmpKumUmsCustArtGrpAll.VUCSShare * 100) / nDXTmpKumUmsCustArtGrpAll.VU : 0;
            nDXTmpKumUmsCustArtGrpAll.setDiffValuesPercent(nDXUmsatzClass, true);
            if (nDXTmpKumUmsCustArtGrpAll.validateWrite())
            {
                nDXTmpKumUmsCustArtGrpAll.write();
            }

            if (lWithProt)
            {
                NDXUmsatzProt::add(umsSignature, "@NDX:NDXAddSalesVoumeShares2", NDXProtStart::Stop, 2);          // Artikelgruppenumsatz-ZL-Anteile den Artikelgruppenumsätzen zufügen 2
            }
        }

        // Nachdem die Artikelgruppenumsätze incl. CL-Anteile der einzelnen Debitoren berechnet wurden,
        // sind die Artikelgruppenumsätze des Rings zu komplettieren
        while select    sum(U01) , sum(U02) , sum(U03) , sum(U04) , sum(U05) , sum(U06) , sum(U07) , sum(U08) , sum(U09) , sum(U10) , sum(U11) , sum(U12) ,
                        sum(VU01), sum(VU02), sum(VU03), sum(VU04), sum(VU05), sum(VU06), sum(VU07), sum(VU08), sum(VU09), sum(VU10), sum(VU11), sum(VU12),
                        sum(UCSShareExcl), sum(VUCSShareExcl), sum(UCSShare), sum(VUCSShare),
                        sum(UACSShareExcl), sum(VUACSShareExcl), sum(UACSShare), sum(VUACSShare),
                        sum(CCSShare), sum(VCCSShare),
                        sum(U), sum(VU)
        from            nDXTmpKumUmsCustArtGrp
        group by        Company, ItemGroup
        where           nDXTmpKumUmsCustArtGrp.UmsSignature        == umsSignature                         &&
                        nDXTmpKumUmsCustArtGrp.MonthYearSignature  == monthYearSignature                   &&
                        nDXTmpKumUmsCustArtGrp.Alliance            == alliance                             &&
                        nDXTmpKumUmsCustArtGrp.Company               != NDXCompanyBE::AllCompanies
        exists join     nDXTmpCustomerAlliance
            where       nDXTmpCustomerAlliance.UmsSignature        == nDXTmpKumUmsCustArtGrp.UmsSignature &&
                        nDXTmpCustomerAlliance.Alliance            == nDXTmpKumUmsCustArtGrp.Alliance     &&
                        nDXTmpCustomerAlliance.CustAccount         == nDXTmpKumUmsCustArtGrp.Child
        {
            if (NDXConstants::DebugModeHP)
            {
                Debug::printDebug(strfmt("@NDX:NDXCompanyItemGrpU01", nDXTmpKumUmsCustArtGrp.Company, nDXTmpKumUmsCustArtGrp.ItemGroup, nDXTmpKumUmsCustArtGrp.U01));          // Firma[%1] Artikelgruppe[%2] U01[%3]
            }
            //Artikelgruppe des Rings
            if (nDXUmsatzClass.parmPartyIdCalculated())
            {
                nDXTmpKumUmsCustArtGrpAll = NDXTmpKumUmsCustArtGrp::findPartyId(umsSignature,
                                                                    monthYearSignature,
                                                                    nDXUmsatzClass.parmPartyIdCalculated(),
                                                                    nDXTmpKumUmsCustArtGrp.Company,
                                                                    nDXTmpKumUmsCustArtGrp.ItemGroup,
                                                                    true);
            }
            else
            {
                nDXTmpKumUmsCustArtGrpAll = NDXTmpKumUmsCustArtGrp::find(umsSignature,
                                                                    monthYearSignature,
                                                                    alliance,
                                                                    alliance,
                                                                    nDXTmpKumUmsCustArtGrp.Company,
                                                                    nDXTmpKumUmsCustArtGrp.ItemGroup,
                                                                    true);
                custTablePartyId = NDXUmsatzClass::getCustTableFromAccount(alliance, nDXTmpKumUmsCustArtGrp.Company);
            }
            // Falls Debitor für diese Gruppe keinen Umsatz gemacht hat, diesen anlegen
            if (!nDXTmpKumUmsCustArtGrpAll)
            {
                nDX_ArtGrp = NDXArtGrp::find(nDXTmpKumUmsCustArtGrp.ItemGroup, '', '');
                nDXTmpKumUmsCustArtGrpAll.UmsSignature        = umsSignature;
                nDXTmpKumUmsCustArtGrpAll.MonthYearSignature  = monthYearSignature;
                nDXTmpKumUmsCustArtGrpAll.Alliance            = alliance;
                nDXTmpKumUmsCustArtGrpAll.Child               = alliance;
                nDXTmpKumUmsCustArtGrpAll.ItemGroup           = nDXTmpKumUmsCustArtGrp.ItemGroup;
                nDXTmpKumUmsCustArtGrpAll.Name                = nDX_ArtGrp.BEZ;
                nDXTmpKumUmsCustArtGrpAll.Company               = nDXTmpKumUmsCustArtGrp.Company;
                nDXTmpKumUmsCustArtGrpAll.Party             = custTablePartyId.Party;
                nDXTmpKumUmsCustArtGrpAll.PartyChild        = custTablePartyId.Party;
            }
            nDXTmpKumUmsCustArtGrpAll.setUmsLfdJTmpKumUmsCustArtGrp(nDXTmpKumUmsCustArtGrp);
            nDXTmpKumUmsCustArtGrpAll.setUmsVJTmpKumUmsCustArtGrp(nDXTmpKumUmsCustArtGrp);
            nDXTmpKumUmsCustArtGrpAll.UCSShare             = nDXTmpKumUmsCustArtGrp.UCSShare;
            nDXTmpKumUmsCustArtGrpAll.VUCSShare            = nDXTmpKumUmsCustArtGrp.VUCSShare;
            nDXTmpKumUmsCustArtGrpAll.CCSShare             = nDXTmpKumUmsCustArtGrp.CCSShare;
            nDXTmpKumUmsCustArtGrpAll.VCCSShare            = nDXTmpKumUmsCustArtGrp.VCCSShare;
            nDXTmpKumUmsCustArtGrpAll.UCSShareExcl         = nDXTmpKumUmsCustArtGrpAll.getUmsLfdJahr();
            nDXTmpKumUmsCustArtGrpAll.VUCSShareExcl        = nDXTmpKumUmsCustArtGrpAll.getUmsVJahr();
            nDXTmpKumUmsCustArtGrpAll.UACSShare            = nDXTmpKumUmsCustArtGrp.UACSShare;
            nDXTmpKumUmsCustArtGrpAll.VUACSShare           = nDXTmpKumUmsCustArtGrp.VUACSShare;
            nDXTmpKumUmsCustArtGrpAll.UACSShareExcl        = nDXUmsatzClass.UAJahrNDXTmpKumUmsCustArtGrp(nDXTmpKumUmsCustArtGrpAll);
            nDXTmpKumUmsCustArtGrpAll.VUACSShareExcl       = nDXUmsatzClass.VUAJahrNDXTmpKumUmsCustArtGrp(nDXTmpKumUmsCustArtGrpAll);
            nDXTmpKumUmsCustArtGrpAll.U                    = nDXTmpKumUmsCustArtGrpAll.UCSShareExcl   + nDXTmpKumUmsCustArtGrpAll.UCSShare;
            nDXTmpKumUmsCustArtGrpAll.VU                   = nDXTmpKumUmsCustArtGrpAll.VUCSShareExcl  + nDXTmpKumUmsCustArtGrpAll.VUCSShare;
            nDXTmpKumUmsCustArtGrpAll.UCSSharePercent      = nDXTmpKumUmsCustArtGrpAll.U  ? (nDXTmpKumUmsCustArtGrpAll.UCSShare * 100)  / nDXTmpKumUmsCustArtGrpAll.U   : 0;
            nDXTmpKumUmsCustArtGrpAll.VUCSSharePercent     = nDXTmpKumUmsCustArtGrpAll.VU ? (nDXTmpKumUmsCustArtGrpAll.VUCSShare * 100) / nDXTmpKumUmsCustArtGrpAll.VU : 0;
            nDXTmpKumUmsCustArtGrpAll.setDiffValuesPercent(nDXUmsatzClass, true);
            if (nDXTmpKumUmsCustArtGrpAll.validateWrite())
            {
                nDXTmpKumUmsCustArtGrpAll.write();
            }
        }

        // Werte für alle Firmen ermitteln
        while select    sum(U01) , sum(U02) , sum(U03) , sum(U04) , sum(U05) , sum(U06) , sum(U07) , sum(U08) , sum(U09) , sum(U10) , sum(U11) , sum(U12) ,
                        sum(VU01), sum(VU02), sum(VU03), sum(VU04), sum(VU05), sum(VU06), sum(VU07), sum(VU08), sum(VU09), sum(VU10), sum(VU11), sum(VU12),
                        sum(UCSShareExcl), sum(VUCSShareExcl),
                        sum(UCSShare), sum(VUCSShare),
                        sum(CCSShare), sum(VCCSShare),
                        sum(UACSShareExcl), sum(VUACSShareExcl),
                        sum(UACSShare), sum(VUACSShare),
                        sum(U), sum(VU)
        from            nDXTmpKumUmsCustArtGrp
        group by        ItemGroup
        where           nDXTmpKumUmsCustArtGrp.UmsSignature        == umsSignature                         &&
                        nDXTmpKumUmsCustArtGrp.MonthYearSignature  == monthYearSignature                   &&
                        nDXTmpKumUmsCustArtGrp.Alliance            == alliance                             &&
                        nDXTmpKumUmsCustArtGrp.Child               == alliance                             &&
                        nDXTmpKumUmsCustArtGrp.Company               != NDXCompanyBE::AllCompanies
        {
            if (NDXConstants::DebugModeHP)
            {
                Debug::printDebug(strfmt("@NDX:NDXCompanyItemGrpU01", nDXTmpKumUmsCustArtGrp.Company, nDXTmpKumUmsCustArtGrp.ItemGroup, nDXTmpKumUmsCustArtGrp.U01));      // Firma[%1] Artikelgruppe[%2] U01[%3]
            }
            //Artikelgruppe des Rings
            if (nDXUmsatzClass.parmPartyIdCalculated())
            {
                nDXTmpKumUmsCustArtGrpAll = NDXTmpKumUmsCustArtGrp::findPartyId(umsSignature,
                                                                    monthYearSignature,
                                                                    nDXUmsatzClass.parmPartyIdCalculated(),
                                                                    NDXCompanyBE::AllCompanies,
                                                                    nDXTmpKumUmsCustArtGrp.ItemGroup,
                                                                    true);
            }
            else
            {
                nDXTmpKumUmsCustArtGrpAll = NDXTmpKumUmsCustArtGrp::find(umsSignature,
                                                                    monthYearSignature,
                                                                    alliance,
                                                                    alliance,
                                                                    NDXCompanyBE::AllCompanies,
                                                                    nDXTmpKumUmsCustArtGrp.ItemGroup,
                                                                    true);
            }

            // Falls Debitor für diese Gruppe keinen Umsatz gemacht hat, diesen anlegen
            if (!nDXTmpKumUmsCustArtGrpAll)
            {
                nDX_ArtGrp = NDXArtGrp::find(nDXTmpKumUmsCustArtGrp.ItemGroup, '', '');
                nDXTmpKumUmsCustArtGrpAll.UmsSignature        = umsSignature;
                nDXTmpKumUmsCustArtGrpAll.MonthYearSignature  = monthYearSignature;
                nDXTmpKumUmsCustArtGrpAll.Alliance            = alliance;
                nDXTmpKumUmsCustArtGrpAll.Child               = alliance;
                nDXTmpKumUmsCustArtGrpAll.ItemGroup           = nDXTmpKumUmsCustArtGrp.ItemGroup;
                nDXTmpKumUmsCustArtGrpAll.Name                = nDX_ArtGrp.BEZ;
                nDXTmpKumUmsCustArtGrpAll.Company             = NDXCompanyBE::AllCompanies;
                nDXTmpKumUmsCustArtGrpAll.Party             = custTablePartyId.Party;
                nDXTmpKumUmsCustArtGrpAll.PartyChild        = CustTable::find(nDXTmpKumUmsCustArtGrp.Child).Party;
            }
            nDXTmpKumUmsCustArtGrpAll.setUmsLfdJTmpKumUmsCustArtGrp(nDXTmpKumUmsCustArtGrp);
            nDXTmpKumUmsCustArtGrpAll.setUmsVJTmpKumUmsCustArtGrp(nDXTmpKumUmsCustArtGrp);
            nDXTmpKumUmsCustArtGrpAll.UCSShare             = nDXTmpKumUmsCustArtGrp.UCSShare;
            nDXTmpKumUmsCustArtGrpAll.VUCSShare            = nDXTmpKumUmsCustArtGrp.VUCSShare;
            nDXTmpKumUmsCustArtGrpAll.CCSShare             = nDXTmpKumUmsCustArtGrp.CCSShare;
            nDXTmpKumUmsCustArtGrpAll.VCCSShare            = nDXTmpKumUmsCustArtGrp.VCCSShare;
            nDXTmpKumUmsCustArtGrpAll.UCSShareExcl         = nDXTmpKumUmsCustArtGrpAll.getUmsLfdJahr();
            nDXTmpKumUmsCustArtGrpAll.VUCSShareExcl        = nDXTmpKumUmsCustArtGrpAll.getUmsVJahr();
            nDXTmpKumUmsCustArtGrpAll.UACSShare            = nDXTmpKumUmsCustArtGrp.UACSShare;
            nDXTmpKumUmsCustArtGrpAll.VUACSShare           = nDXTmpKumUmsCustArtGrp.VUACSShare;
            nDXTmpKumUmsCustArtGrpAll.UACSShareExcl        = nDXUmsatzClass.UAJahrNDXTmpKumUmsCustArtGrp(nDXTmpKumUmsCustArtGrpAll);
            nDXTmpKumUmsCustArtGrpAll.VUACSShareExcl       = nDXUmsatzClass.VUAJahrNDXTmpKumUmsCustArtGrp(nDXTmpKumUmsCustArtGrpAll);
            nDXTmpKumUmsCustArtGrpAll.U                    = nDXTmpKumUmsCustArtGrpAll.UCSShareExcl   + nDXTmpKumUmsCustArtGrpAll.UCSShare;
            nDXTmpKumUmsCustArtGrpAll.VU                   = nDXTmpKumUmsCustArtGrpAll.VUCSShareExcl  + nDXTmpKumUmsCustArtGrpAll.VUCSShare;
            nDXTmpKumUmsCustArtGrpAll.UCSSharePercent      = nDXTmpKumUmsCustArtGrpAll.U  ? (nDXTmpKumUmsCustArtGrpAll.UCSShare * 100)  / nDXTmpKumUmsCustArtGrpAll.U   : 0;
            nDXTmpKumUmsCustArtGrpAll.VUCSSharePercent     = nDXTmpKumUmsCustArtGrpAll.VU ? (nDXTmpKumUmsCustArtGrpAll.VUCSShare * 100) / nDXTmpKumUmsCustArtGrpAll.VU : 0;
            nDXTmpKumUmsCustArtGrpAll.setDiffValuesPercent(nDXUmsatzClass, true);
            if (nDXTmpKumUmsCustArtGrpAll.validateWrite())
            {
                nDXTmpKumUmsCustArtGrpAll.write();
            }
        }
        //TODO: DebuC Prüfung erforderlich ob dieser Aufruf noch Sinn macht. Nachfolgendes Query kann mit doppelter Übergabe der Alliance eig keinen Satz ermitteln und würde die Methode überspringen
        //nDXTmpKumUmsCustArtGrp::setUmsAnteil(umsSignature, monthYearSignature, alliance, alliance, nDXUmsatzClass, true);        // Umsatzanteile neu berechnen
        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
        {
            infoAddition = strFmt("@NDX:NDXErrorTmpKumUmsCustArtGrpAddition", sessionId(), nDXTmpKumUmsCustArtGrpAll.Alliance, nDXTmpKumUmsCustArtGrpAll.Child, nDXTmpKumUmsCustArtGrpAll.ItemGroup, nDXTmpKumUmsCustArtGrpAll.UmsSignature, nDXTmpKumUmsCustArtGrpAll.MonthYearSignature);
            infoAddition += "NDXTmpKumUmsCustArtGrp:350";
            throw Error(strFmt("@NDXBase:NDXDeadLock", tableId2Name(nDXTmpKumUmsCustArtGrpAll.TableId)) + infoAddition);
        }
        else
        {
            sleep(NDXExceptionConstants::RetryInterval500);
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
        {
            infoAddition = strFmt("@NDX:NDXErrorTmpKumUmsCustArtGrpAddition", sessionId(), nDXTmpKumUmsCustArtGrpAll.Alliance, nDXTmpKumUmsCustArtGrpAll.Child, nDXTmpKumUmsCustArtGrpAll.ItemGroup, nDXTmpKumUmsCustArtGrpAll.UmsSignature, nDXTmpKumUmsCustArtGrpAll.MonthYearSignature);
            infoAddition += "NDXTmpKumUmsCustArtGrp:364";
            throw Error(strFmt("@NDXBase:NDXUpdateConflict", tableId2Name(nDXTmpKumUmsCustArtGrpAll.TableId)) + infoAddition);
        }
        else
        {
            sleep(NDXExceptionConstants::RetryInterval500);
            retry;
        }
    }
    catch (Exception::Error)
    {
        if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
        {
            infoAddition = strFmt("@NDX:NDXErrorTmpKumUmsCustArtGrpAddition", sessionId(), nDXTmpKumUmsCustArtGrpAll.Alliance, nDXTmpKumUmsCustArtGrpAll.Child, nDXTmpKumUmsCustArtGrpAll.ItemGroup, nDXTmpKumUmsCustArtGrpAll.UmsSignature, nDXTmpKumUmsCustArtGrpAll.MonthYearSignature);
            infoAddition += "NDXTmpKumUmsCustArtGrp:378";
            throw Error(strFmt("@NDXBase:NDXTableError", tableId2Name(nDXTmpKumUmsCustArtGrpAll.TableId)) + infoAddition);
        }
        else
        {
            sleep(NDXExceptionConstants::RetryInterval500);
            retry;
        }
    }
    catch (ex)
    {
        str errorMessage = ex.Message + NDXGlobalConstants::NewLine;
        errorMessage += "Error: NDXTmpKumUmsCustArtGrp:390" + NDXGlobalConstants::NewLine;
        errorMessage += NDXHelperCommon::callStack2str();
        throw Error(errorMessage);
    }


}

void setDiffValuesPercent(nDXUmsatzClass _umsatzClass, boolean lInclCS = false)
{
    real        umsLfdJ;
    real        umsVJ;
    ;
    if (_UmsatzClass.parmNdxUmsatzAbschluss().parmJahr() <= _UmsatzClass.parmYearlfdJ())
    {
        umsLfdJ = lInclCS ? this.UCSShare  + this.UCSShareExcl  : this.UCSShareExcl;
        umsVJ   = lInclCS ? this.VUCSShare + this.VUCSShareExcl : this.VUCSShareExcl;
    }
    else
    {
        umsLfdJ = lInclCS ? this.U  : this.getUmsLfdJahr();
        umsVJ   = lInclCS ? this.VU : this.getUmsVJahr();
    }
    if (!umsVJ && !umsLfdJ)
    {
        this.DiffJahr   = 0;
    }
    else if (!umsVJ && umsLfdJ)
    {
        this.DiffJahr   = 100;
    }
    else
    {
        if (umsVJ)
        {
            this.DiffJahr = ((100 * umsLfdJ) / umsVJ) - 100;
        }
        else
        {
            this.DiffJahr = 0;
        }
    }
    if (umsLfdJ >= 0 && umsVJ < 0)
    {
        this.DiffJahr = 100;
    }
    else if (umsLfdJ <  0 && umsVJ < 0)
    {
        this.DiffJahr = this.DiffJahr * -1;
    }
}

