                    nDXTmpKumUmsCustArtGrp.VUACSShareExcl  = nDX_UmsatzClass.VUAJahrNDXTmpKumUmsCustArtGrp(nDXTmpKumUmsCustArtGrp);

                    nDXTmpKumUmsCustArtGrp.U               = nDXTmpKumUmsCustArtGrp.UCSShareExcl;
