                    ttscommit;

                    ++nAnz1;
                    nDX_JobManagerJobs.setAction("@NDX:NDXSalesSharesPerCmpItemGroup", strfmt('%1-%2-%3', alliance, partyId, nDXTmpKumUmsCustArtGrp.ItemGroup), nAnz1);
