static void getUmsCS(NDXTmpCSAlliance  l_NDX_TmpCSAlliance,
                 NDXYear            jahr,
                 boolean            lExclude,
                 boolean            lAktJahr = true,
                 boolean            lTestImport = false)
{

    NDXKumUmsCustArtGrp        nDX_KumUmsCustArtGrp;
    NDXTmpCSAllianceArtGrp     nDX_TmpCSAllianceArtGrp;

    NDXCompanyBE                firma;
    NDXKdNr                     nDX_KdNr;

    Query                       q;
    QueryRun                    qr;
    QueryBuildDataSource        qbds;
    RecordSortedList            recordSortedList;
    ;

    ttsbegin;
    recordSortedList = new RecordSortedList(tablenum(NDXTmpCSAllianceArtGrp));
    recordSortedList.sortOrder(fieldnum(NDXTmpCSAllianceArtGrp, UmsSignature),
                           fieldnum(NDXTmpCSAllianceArtGrp, MonthYearSignature),
                           fieldnum(NDXTmpCSAllianceArtGrp, Exclude),
                           fieldnum(NDXTmpCSAllianceArtGrp, Company),
                           fieldnum(NDXTmpCSAllianceArtGrp, Alliance),
                           fieldnum(NDXTmpCSAllianceArtGrp, CustAccount),
                           fieldnum(NDXTmpCSAllianceArtGrp, CentralStoreId),
                           fieldnum(NDXTmpCSAllianceArtGrp, ArtGrp));
    firma       = NDXHelperCommon::CompanyId2NDXCompany(l_NDX_TmpCSAlliance.Company, lTestImport);
    nDX_KdNr    = str2int(l_NDX_TmpCSAlliance.CentralStoreId);


    // über alle Artikelgruppen des Zentrallagers die Werte ermitteln
    q       = new Query();
    qbds    = q.addDataSource(tablenum(NDXKumUmsCustArtGrp));
    qbds.addRange(fieldnum(NDXKumUmsCustArtGrp, KdNr)).value(QueryValue(nDX_KdNr));
    qbds.addRange(fieldnum(NDXKumUmsCustArtGrp, Jahr)).value(QueryValue(jahr));
    qbds.addRange(fieldnum(NDXKumUmsCustArtGrp, Companys)).value(QueryValue(firma));
    qr      = new QueryRun(q);
    while (qr.next())
    {
        nDX_KumUmsCustArtGrp = qr.get(tablenum(NDXKumUmsCustArtGrp));

        nDX_TmpCSAllianceArtGrp = NDXTmpCSAllianceArtGrp::find(l_NDX_TmpCSAlliance.UmsSignature,
                                                            l_NDX_TmpCSAlliance.MonthYearSignature,
                                                            lExclude,
                                                            l_NDX_TmpCSAlliance.Company,
                                                            l_NDX_TmpCSAlliance.Alliance,
                                                            l_NDX_TmpCSAlliance.CustAccount,
                                                            l_NDX_TmpCSAlliance.CentralStoreId,
                                                            nDX_KumUmsCustArtGrp.ArtGrp(),
                                                            true);

        nDX_TmpCSAllianceArtGrp.UmsSignature        = l_NDX_TmpCSAlliance.UmsSignature;
