/// <summary>
/// DebuC 16.10.23
/// last modified: PaffH 19.02.25
/// </summary>
/// <param name = "umsSignature">NDXUmsSignature</param>
/// <param name = "monthYearSignature">NDXMonthYearSignature</param>
/// <param name = "alliance">CustAccount</param>
/// <param name = "child">CustAccount</param>
/// <param name = "firma">NDXCompanyBE</param>
/// <param name = "artGrp">NDXItemGroup</param>
/// <param name = "l_forUpdate">boolean</param>
/// <param name = "_pessimisticLock">boolean</param>
/// <returns>NDXTmpKumUmsCustArtGrp</returns>
static NDXTmpKumUmsCustArtGrp find(
    NDXUmsSignature umsSignature,
    NDXMonthYearSignature monthYearSignature,
    CustAccount alliance,
    CustAccount child,
    NDXCompanyBE firma,
    NDXItemGroup artGrp,
    boolean l_forUpdate = false,
    boolean _pessimisticLock = false)
{
    NDXTmpKumUmsCustArtGrp umsatz;
    ;
    umsatz.selectForUpdate(l_forUpdate);
    if (_pessimisticLock)
    {
        umsatz.concurrencyModel(ConcurrencyModel::Pessimistic);
    }

    if (alliance && child)
    {
        select      umsatz
            where   umsatz.UmsSignature         == umsSignature         &&
                    umsatz.MonthYearSignature   == monthYearSignature   &&
                    umsatz.Company              == firma                &&
                    umsatz.ItemGroup            == artGrp               &&
                    umsatz.Alliance             == alliance             &&
                    umsatz.Child                == child;
    }

    return umsatz;
}

/// <summary>
/// DebuC 16.10.23
/// last modified: PaffH 19.02.25
/// </summary>
/// <param name = "umsSignature">NDXUmsSignature</param>
/// <param name = "monthYearSignature">NDXMonthYearSignature</param>
/// <param name = "party">RefRecId</param>
/// <param name = "firma">NDXCompanyBE</param>
/// <param name = "artGrp">NDXItemGroup</param>
/// <param name = "l_forUpdate">boolean</param>
/// <param name = "_pessimisticLock">boolean</param>
/// <returns>NDXTmpKumUmsCustArtGrp</returns>
static NDXTmpKumUmsCustArtGrp findPartyId(
    NDXUmsSignature        umsSignature,
    NDXMonthYearSignature  monthYearSignature,
    RefRecId                party,
    NDXCompanyBE             firma,
    NDXItemGroup            artGrp,
    boolean                 l_forUpdate = false,
    boolean _pessimisticLock = false)
{
    NDXTmpKumUmsCustArtGrp umsatz;
    umsatz.selectForUpdate(l_forUpdate);
    if (_pessimisticLock)
    {
        umsatz.concurrencyModel(ConcurrencyModel::Pessimistic);
    }

    select      umsatz
    where   umsatz.UmsSignature         == umsSignature         &&
            umsatz.MonthYearSignature   == monthYearSignature   &&
            umsatz.Company              == firma                &&
            umsatz.ItemGroup            == artGrp               &&
            umsatz.Party                == party;

    return umsatz;
}

