/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <param name = "_umsSignature">NDXUmsSignature</param>
/// <param name = "_alliance">CustAccount</param>
static void deleteRecords(NDXUmsSignature _umsSignature, CustAccount _alliance)
{
    NDXTmpKumUmsCustArtGrp          table;
    ;

    table.skipDataMethods(true);
    table.skipAosValidation(true);
    table.skipDatabaseLog(true);
    table.skipEvents(true);
    table.skipDeleteActions(true);

    if (_alliance)
    {
        delete_from     table
                where       table.UmsSignature == _umsSignature &&
                            table.Alliance     == _alliance;
    }
    else
    {
        delete_from     table
                where       table.UmsSignature == _umsSignature;
    }
}

/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <param name = "_copyTo">NDXUmsSignature</param>
/// <param name = "_copyToOld">NDXUmsSignature</param>
/// <param name = "_sic">boolean</param>
/// <param name = "_copyFromSic">NDXUmsSignature</param>
/// <param name = "_only4Alliance">CustAccount</param>
static void updateRecords(NDXUmsSignature _copyTo,NDXUmsSignature _copyToOld, boolean _sic, NDXUmsSignature _copyFromSic, CustAccount _only4Alliance)
{

    // bestehende Daten sichern
    NDXTmpKumUmsCustArtGrp      table;
    Common                      commonCopySic;
    int64                       anzBefore, anzAfter;
    DictTable                   dictTable;
    NDXUmsSignature         l_copyFrom2 = _copyTo;
    NDXUmsSignature         l_copyTo2   = _copyToOld;        
    boolean                 l_lSic      = _sic;

    //BP deviation documented
    table.skipDataMethods(true);
    table.skipAosValidation(true);
    table.skipDatabaseLog(true);
    table.skipEvents(true);
    table.skipDeleteActions(true);

    // Sicherung der CopyFrom-Daten
    if (l_lSic)
    {
        dictTable       = new DictTable(table.TableId);
        commonCopySic   = dictTable.makeRecord();
        ttsbegin;

        // alte Sicherung löschen
        if (_only4Alliance)
        {
            delete_from     table
                where       table.UmsSignature == _copyFromSic &&
                            table.Alliance     == _only4Alliance;
        }
        else
        {
            delete_from     table
                where       table.UmsSignature == _copyFromSic;
        }

        // aktuelle Daten sichern
        if (_only4Alliance)
        {
            while select table
                where    table.UmsSignature    == l_copyFrom2      &&
                            table.Alliance        == _only4Alliance
            {
                buf2Buf(table, commonCopySic);
                commonCopySic.(dictTable.fieldname2id(identifierstr(UmsSignature))) = _copyFromSic;
                commonCopySic.doInsert();
            }
        }
        else
        {
            while select table
                where    table.UmsSignature == l_copyFrom2
            {
                buf2Buf(table, commonCopySic);
                commonCopySic.(dictTable.fieldname2id(identifierstr(UmsSignature))) = _copyFromSic;
                commonCopySic.doInsert();
            }
        }
        ttscommit;
    }

    if (_only4Alliance)
    {
        anzBefore = (select     count(recid)
                        from    NDXTmpKumUmsCustArtGrp
                        where   NDXTmpKumUmsCustArtGrp.UmsSignature == l_copyTo2 &&
                                NDXTmpKumUmsCustArtGrp.Alliance     == _only4Alliance).recid;

        update_recordset        table
            setting             UmsSignature = l_copyTo2
            where               table.UmsSignature == l_copyFrom2 &&
                                table.Alliance     == _only4Alliance;

        anzAfter  = (select     count(recid)
                        from    NDXTmpKumUmsCustArtGrp
                        where   NDXTmpKumUmsCustArtGrp.UmsSignature == l_copyTo2 &&
                                NDXTmpKumUmsCustArtGrp.Alliance     == _only4Alliance).recid;
    }
    else
    {
        anzBefore = (select     count(recid)
                        from    NDXTmpKumUmsCustArtGrp
                        where   NDXTmpKumUmsCustArtGrp.UmsSignature == l_copyTo2).recid;

        update_recordset        table
            setting             UmsSignature = l_copyTo2
            where               table.UmsSignature == l_copyFrom2;

        anzAfter  = (select     count(recid)
                        from    NDXTmpKumUmsCustArtGrp
                        where   NDXTmpKumUmsCustArtGrp.UmsSignature == l_copyTo2).recid;
    }
    if (_copyToOld)
    {
        info(strfmt("@NDX:NDXRecordsSavedIn", NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())), anzAfter - anzBefore, tableId2Name(table.TableId), l_copyTo2));       // [%1] [%2] Records in [%3] unter [%4] gesichert
    }
    else
    {
        info(strfmt("@NDX:NDXRecordsTransferedTo", NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())), anzAfter - anzBefore, tableId2Name(table.TableId), l_copyTo2));       // [%1] [%2] Records in [%3] unter [%4] übertragen
    }

}

/// <summary>
/// PaffH 05.05.25
/// last modified: PaffH 03.07.25
/// </summary>
public void update()
{
    str infoAddition = '';
    System.Exception ex;
    try
    {
        infoAddition = strFmt("@NDX:NDXErrorTmpKumUmsCustArtGrpAddition", sessionId(), this.Alliance, this.Child, this.ItemGroup, this.UmsSignature, this.MonthYearSignature);
        infoAddition += strFmt(' RecId [%1]', this.RecId);
        this.SessionIdLast = sessionId();
        this.RecVersionLast = this.RecVersion;
        if (NDXBatchProcessingParameters::find().WriteLog2File)
        {
            NDXHelperCommon::writeToTextFile(@'c:\logs\NDXBatchMultithreading.log', 
            strFmt('time [%1]; session [%2]; Alliance [%3]; table [%4]; recid [%5]; recversion [%6]; type [%7]; action [%8]',
                NDXHelperCommon::miliseconds2Str(), 
                sessionId(), 
                this.Alliance,
                'NDXTmpKumUmsCustArtGrp',
                this.RecId,
                this.RecVersion,
                2,
                'NDXTmpKumUmsCustArtGrp.update()'));
        }
        super();
    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
        {
            infoAddition += NDXGlobalConstants::NewLine + 'NDXTmpKumUmsCustArtGrp:1160';
            infoAddition += NDXGlobalConstants::NewLine + NDXHelperCommon::callStack2str();
            Error(strFmt("@NDXBase:NDXDeadLock", tableId2Name(tableNum(NDXTmpKumUmsCustArtGrp))) + infoAddition);
            throw;
        }
        else
        {
            sleep(NDXExceptionConstants::RetryInterval500);
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        infoAddition += NDXGlobalConstants::NewLine + 'NDXTmpKumUmsCustArtGrp:1171';
        infoAddition += NDXGlobalConstants::NewLine + NDXHelperCommon::callStack2str();
        Error(strFmt("@NDXBase:NDXUpdateConflict", tableId2Name(tableNum(NDXTmpKumUmsCustArtGrp))) + infoAddition);
        throw;
    }
    catch (Exception::Error)
    {
        if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
        {
            infoAddition += NDXGlobalConstants::NewLine + 'NDXTmpKumUmsCustArtGrp:1178';
            infoAddition += NDXGlobalConstants::NewLine + NDXHelperCommon::callStack2str();
            Error(strFmt("@NDXBase:NDXTableError", tableId2Name(tableNum(NDXTmpKumUmsCustArtGrp))) + infoAddition);
            throw;

        }
        else
        {
            sleep(NDXExceptionConstants::RetryInterval500);
            retry;
        }
    }
    catch (ex)
    {
        Error('Error: NDXTmpKumUmsCustArtGrp:1189');
        str errorMessage = ex.Message + NDXGlobalConstants::NewLine;
        errorMessage += ' NDXTmpKumUmsCustArtGrp:1178' + NDXGlobalConstants::NewLine;
        errorMessage += NDXHelperCommon::callStack2str();
        Error(errorMessage + infoAddition);
        throw;
    }
}
